def extract_query_params(raw_query_items: list[tuple[str, str]]) -> dict[str, Any]:
    values = {}
    for key, value in raw_query_items:
        if key in values:
            if not isinstance(values[key], list):
                values[key] = [values[key]]
            values[key].append(value)
        else:
            values[key] = value
    return values
